ss="block font-semibold text-sm mb-2">Kuota (kosong = tanpa batas)</label><input type="number" min="1" name="quota" value="{{old('quota',$event->quota)}}" class="w-full rounded-xl border-slate-200"></div><div><label class="block font-semibold text-sm mb-2">Jenis reward *</label><select required name="reward_type" class="w-full rounded-xl border-slate-200"><option value="jam_plus" @selected(old('reward_type',$event->reward_type?->value)==='jam_plus')>Jam Plus</option><option value="soft_skill" @selected(old('reward_type',$event->reward_type?->value)==='soft_skill')>Soft Skill</option><option value="both" @selected(old('reward_type',$event->reward_type?->value)==='both')>Keduanya</option></select></div><div><label class="block font-semibold text-sm mb-2">Nilai Jam Plus</label><input type="number" step="0.01" min="0" name="jam_plus_offer" value="{{old('jam_plus_offer',$event->jam_plus_offer)}}" class="w-full rounded-xl border-slate-200"></div><div><label class="block font-semibold text-sm mb-2">Poin Soft Skill</label><input type="number" step="0.01" min="0" name="soft_skill_points_offer" value="{{old('soft_skill_points_offer',$event->soft_skill_points_offer)}}" class="w-full rounded-xl border-slate-200"></div></div><div><label class="block font-semibold text-sm mb-2">Target peserta *</label><select name="audience_scope" class="w-full rounded-xl border-slate-200"><option value="all" @selected(old('audience_scope',$event->audience_scope?->value)==='all')>Semua Prodi</option><option value="selected" @selected(old('audience_scope',$event->audience_scope?->value)==='selected')>Prodi tertentu (pilih di bawah)</option></select><div class="grid sm:grid-cols-3 gap-2 mt-3">@foreach($programs as $program)<label class="text-sm flex gap-2 items-center"><input type="checkbox" name="target_programs[]" value="{{$program->id}}" @checked(in_array($program->id,old('target_programs',$event->exists?$event->targets()->pluck('study_program_id')->all():[])))>{{$program->name}}</label>@endfore